import{_ as a,o as s,c as t,a2 as r}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"投诉封停使用指南","description":"","frontmatter":{"title":"投诉封停使用指南"},"headers":[],"relativePath":"ops-knowledge-base/presales-support/complaint-suspension-guide.md","filePath":"ops-knowledge-base/presales-support/complaint-suspension-guide.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/presales-support/complaint-suspension-guide.md"};function l(i,e,n,p,u,d){return s(),t("div",null,[...e[0]||(e[0]=[r('<h2 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>本文档介绍如何查看因 Abuse（滥用）投诉而被封停的 IP，了解封停原因，以及在完成整改后如何申请解封，恢复 IP 的正常使用。</p><p><strong>适用产品：</strong></p><ul><li>VPS（Virtual Private Server）</li><li>裸机云（Bare Metal Cloud）</li><li>物理服务器（Dedicated Server）</li></ul><hr><h2 id="一、功能概述" tabindex="-1">一、功能概述 <a class="header-anchor" href="#一、功能概述" aria-label="Permalink to &quot;一、功能概述&quot;">​</a></h2><p><strong>投诉封停（Abuse Suspension）</strong> 页面用于展示因 Abuse 投诉或违反平台使用政策而被封停的 IP 信息。</p><p>客户可通过该页面查看被封停 IP 的相关信息，了解封停原因，在完成整改后提交工单申请解封，以恢复 IP 的正常使用。</p><hr><h2 id="二、进入投诉封停页面" tabindex="-1">二、进入投诉封停页面 <a class="header-anchor" href="#二、进入投诉封停页面" aria-label="Permalink to &quot;二、进入投诉封停页面&quot;">​</a></h2><p>登录 <strong>Raksmart 客户后台</strong>，进入：</p><p><strong>客户中心 → 技术支持 → 投诉封停（Abuse Suspension）</strong></p><p>进入后，可查看 <strong>我的封停列表（My Suspension List）</strong> 页面。</p><hr><h2 id="三、查看封停信息" tabindex="-1">三、查看封停信息 <a class="header-anchor" href="#三、查看封停信息" aria-label="Permalink to &quot;三、查看封停信息&quot;">​</a></h2><p>在 <strong>我的封停列表</strong> 页面中，可查看当前因投诉而被封停的 IP 信息，包括：</p><ul><li><strong>封停 IP</strong>：当前被封停的 IP 地址。</li><li><strong>封停原因</strong>：显示封停原因（例如：<strong>Blocked due to Abuse</strong>）。</li><li><strong>封停时间</strong>：IP 被封停的时间。</li><li><strong>状态</strong>：当前 IP 的状态（例如：<strong>Blocked</strong>）。</li></ul><hr><h2 id="四、如何申请解封" tabindex="-1">四、如何申请解封 <a class="header-anchor" href="#四、如何申请解封" aria-label="Permalink to &quot;四、如何申请解封&quot;">​</a></h2><p>如果您的 IP 已被封停，请按照以下步骤处理：</p><ol><li><p>查看封停信息，确认投诉原因及涉及的问题。</p></li><li><p>根据投诉内容完成整改，删除或修复相关违规内容或服务。</p></li><li><p>进入 <strong>技术支持</strong> 页面提交工单。</p></li><li><p>在工单中提供以下信息：</p><ul><li>被封停的 IP 地址；</li><li>问题说明；</li><li>已完成的整改措施。</li></ul></li><li><p>技术人员收到工单后，将根据整改情况进行审核，并确认是否恢复 IP 的正常使用。</p></li></ol><hr><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>⚠️ 如未完成整改，仅提交解封申请，可能无法通过审核。</p><p>⚠️ 提交解封申请前，请确保投诉涉及的问题已全部处理完成。</p><p>⚠️ 如同一业务再次发生 Abuse 投诉，平台可能根据相关服务政策采取进一步处理措施，包括追加处罚或永久封停。</p><hr>',27)])])}const c=a(o,[["render",l]]);export{g as __pageData,c as default};
